problems.codeCpp:
class Solution {
public:
    ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
        // dummy 虚拟头节点：结果第一个节点的拼接与后续完全一致，免去特判
        ListNode dummy(0);
        ListNode* cur = &dummy;
        int carry = 0;                     // carry 进位，初始为 0
        // 只要还有位没加完，或还有进位没落地，就继续循环
        while (l1 || l2 || carry) {
            int a = l1 ? l1->val : 0;      // 短链表走完后按 0 补位
            int b = l2 ? l2->val : 0;
            int s = a + b + carry;         // 当前位总和 = 两个数位 + 低位进位
            carry = s / 10;                // 新进位：满十进一
            cur->next = new ListNode(s % 10);  // 本位只留下个位数字
            cur = cur->next;
            l1 = l1 ? l1->next : nullptr;
            l2 = l2 ? l2->next : nullptr;
        }
        return dummy.next;                 // dummy.next 才是真正的结果头节点
    }
};

