// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：m（第一条链表长度）
//   第二行：m 个整数（第一条链表，逆序存放一个非负整数）
//   第三行：n（第二条链表长度）
//   第四行：n 个整数（第二条链表，逆序存放一个非负整数）
// 输出格式：一行，和链表的序列，空格分隔
#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* n = nullptr) : val(x), next(n) {}
};

ListNode* build(const vector<int>& nums) {
    ListNode dummy(0);                 // 哨兵串起整条链
    ListNode* cur = &dummy;
    for (int x : nums) {
        cur->next = new ListNode(x);
        cur = cur->next;
    }
    return dummy.next;
}

ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode dummy(0);
    ListNode* cur = &dummy;
    int carry = 0;
    while (l1 || l2 || carry) {        // 还有位没加完或进位没落地就继续
        int a = l1 ? l1->val : 0;      // 短链表走完后按 0 补位
        int b = l2 ? l2->val : 0;
        int s = a + b + carry;
        carry = s / 10;                // 满十进一
        cur->next = new ListNode(s % 10);
        cur = cur->next;
        if (l1) l1 = l1->next;
        if (l2) l2 = l2->next;
    }
    return dummy.next;
}

int main() {
    ios::sync_with_stdio(false);       // 关闭同步，读入更快
    cin.tie(nullptr);

    int m;
    cin >> m;
    vector<int> a(m);
    for (auto& x : a) cin >> x;
    int n;
    cin >> n;
    vector<int> b(n);
    for (auto& x : b) cin >> x;

    ListNode* head = addTwoNumbers(build(a), build(b));
    string out;
    for (ListNode* p = head; p; p = p->next) {
        if (!out.empty()) out += ' ';  // 数字之间空格分隔
        out += to_string(p->val);
    }
    cout << out << endl;
    return 0;
}

