# 链表节点定义
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

class Solution:
    def removeNthFromEnd(self, head: ListNode, n: int) -> ListNode:
        # dummy 虚拟头节点：删除头节点时也能统一用『前驱跳过目标』的写法
        dummy = ListNode(0, head)
        fast = slow = dummy
        # 快指针先走 n+1 步，与慢指针拉开 n+1 个节点的间隔
        for _ in range(n + 1):
            fast = fast.next
        # 快慢同步前进，直到快指针越过链表尾部
        while fast:
            fast = fast.next
            slow = slow.next
        # 此时 slow 是倒数第 n+1 个节点，即待删节点的前驱
        slow.next = slow.next.next  # 跳过倒数第 n 个节点，完成删除
        return dummy.next

