// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（链表长度）
//   第二行：n 个整数（链表节点值）
//   第三行：k（删除倒数第 k 个节点，1 <= k <= n）
// 输出格式：一行，删除后的链表序列，空格分隔（空链表输出空行）
#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* n = nullptr) : val(x), next(n) {}
};

ListNode* build(const vector<int>& nums) {
    ListNode dummy(0);                 // 哨兵串起整条链
    ListNode* cur = &dummy;
    for (int x : nums) {
        cur->next = new ListNode(x);
        cur = cur->next;
    }
    return dummy.next;
}

ListNode* removeNthFromEnd(ListNode* head, int k) {
    ListNode dummy(0, head);
    ListNode* fast = &dummy;
    ListNode* slow = &dummy;
    for (int i = 0; i <= k; ++i) fast = fast->next;  // 快指针先走 k+1 步拉开间隔
    while (fast) {                     // 同步前进直到 fast 越过尾部
        fast = fast->next;
        slow = slow->next;
    }
    slow->next = slow->next->next;     // slow 是待删节点的前驱，跳过它完成删除
    return dummy.next;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<int> nums(n);
    for (auto& x : nums) cin >> x;
    int k;
    cin >> k;

    ListNode* head = removeNthFromEnd(build(nums), k);
    string out;
    for (ListNode* p = head; p; p = p->next) {
        if (!out.empty()) out += ' ';
        out += to_string(p->val);
    }
    cout << out << endl;               // 空链表时输出空行
    return 0;
}

