class Solution {
public:
    ListNode* mergeTwoLists(ListNode* list1, ListNode* list2) {
        // dummy 虚拟头节点：结果链表有了统一拼接起点，无需特判头
        ListNode dummy(0);
        ListNode* cur = &dummy;
        // 两条链表都没走完时，逐个比较当前头节点
        while (list1 && list2) {
            if (list1->val <= list2->val) {  // 取较小者（<= 保证合并稳定）
                cur->next = list1;           // 摘接 list1 的头节点
                list1 = list1->next;         // list1 头指针后移
            } else {
                cur->next = list2;
                list2 = list2->next;
            }
            cur = cur->next;                 // 结果链表尾指针后移
        }
        // 有一条已走完：剩余那条本身有序，整段接上即可
        cur->next = list1 ? list1 : list2;
        return dummy.next;
    }
};

