problems.codeCpp:
class Solution {
public:
    ListNode* mergeKLists(vector<ListNode*>& lists) {
        // 小根堆：元素是 (节点值, 序号, 节点指针)，val 相同时比序号，避免比较指针
        using Item = tuple<int, int, ListNode*>;
        priority_queue<Item, vector<Item>, greater<Item>> heap;
        int cnt = 0;                             // 序号计数器：同值节点的次序保证
        // 1) 把每条链表的当前头作为候选入堆
        for (ListNode* node : lists) {
            if (node) heap.push({node->val, cnt++, node});
        }
        ListNode dummy(0);                       // dummy 虚拟头节点：统一拼接起点
        ListNode* cur = &dummy;
        // 2) 反复弹出全局最小节点，接到结果尾部
        while (!heap.empty()) {
            auto [val, seq, node] = heap.top();  // 弹出 k 个候选中的最小者
            heap.pop();
            cur->next = node;                    // 接到结果尾部
            cur = cur->next;
            if (node->next) {                    // 该节点在原链表中的后继补进堆
                heap.push({node->next->val, cnt++, node->next});
            }
        }
        return dummy.next;
    }
};

