//   接下来 k 行：每行先给该链表长度 m，后跟 m 个升序整数（m 可为 0）
// 输出格式：一行，合并后的升序序列，空格分隔（空结果输出空行）
#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* n = nullptr) : val(x), next(n) {}
};

ListNode* build(const vector<int>& nums) {
    ListNode dummy(0);
