    for (int x : nums) {
        cur->next = new ListNode(x);
        cur = cur->next;
    }
    return dummy.next;
}

ListNode* mergeKLists(const vector<ListNode*>& heads) {
    // 小根堆：元素是 (节点值, 序号, 节点指针)，val 相同时比序号，避免比较指针
    using Item = tuple<int, int, ListNode*>;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    int cnt = 0;
    for (ListNode* node : heads) {     // 每条链的当前头作为候选入堆
        if (node) heap.push({node->val, cnt++, node});
    }
    ListNode dummy(0);
    ListNode* cur = &dummy;
    while (!heap.empty()) {            // 反复弹出全局最小节点
        auto [val, seq, node] = heap.top();
        heap.pop();
        cur->next = node;              // 接到结果尾部
        cur = cur->next;
        if (node->next) {              // 该节点在原链表中的后继补进堆
            heap.push({node->next->val, cnt++, node->next});
        }
    }
    return dummy.next;
}

