class Solution {
    // 堆元素：val 相同时按 seq 决胜，避免直接比较 ListNode 对象
    private static class Item implements Comparable<Item> {
        int val, seq;
        ListNode node;
        Item(int v, int s, ListNode n) { val = v; seq = s; node = n; }
        public int compareTo(Item o) {
            return val != o.val
                ? Integer.compare(val, o.val) : Integer.compare(seq, o.seq);
        }
    }

    public ListNode mergeKLists(ListNode[] lists) {
        // 1) 小根堆：把每条链表的当前头作为候选入堆
        PriorityQueue<Item> heap = new PriorityQueue<>();
        int cnt = 0;
        for (ListNode node : lists) {
            if (node != null) heap.offer(new Item(node.val, cnt++, node));
        }
        // dummy 虚拟头节点：结果链表的统一拼接起点
        ListNode dummy = new ListNode(0), cur = dummy;
        // 2) 反复弹出全局最小节点，接到结果尾部
        while (!heap.isEmpty()) {
            Item top = heap.poll();          // 弹出 k 个候选中的最小者
            cur.next = top.node;             // 接到结果尾部
            cur = cur.next;
            if (top.node.next != null) {     // 该节点在原链表中的后继补进堆
                heap.offer(new Item(top.node.next.val, cnt++, top.node.next));
            }
        }
        return dummy.next;
    }
}

problems.codeJs:
/**
 * @param {ListNode[]} lists k 条升序链表的头节点数组
 * @return {ListNode} 合并后的升序链表头节点
 */
var mergeKLists = function (lists) {
  // 小根堆用数组手写模拟：元素为 { val, seq, node }，val 相同时比 seq
  const heap = [];
  const less = (a, b) => (a.val !== b.val ? a.val < b.val : a.seq < b.seq);
  const push = (item) => {             // 尾部插入后一路上浮
    heap.push(item);
    let i = heap.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (!less(heap[i], heap[p])) break;
      [heap[i], heap[p]] = [heap[p], heap[i]];
      i = p;
    }
  };
  const pop = () => {                  // 弹出堆顶，尾元素补位后下沉归位
    const top = heap[0], last = heap.pop();
    if (heap.length) {
      heap[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < heap.length && less(heap[l], heap[m])) m = l;
        if (r < heap.length && less(heap[r], heap[m])) m = r;
        if (m === i) break;
        [heap[i], heap[m]] = [heap[m], heap[i]];
        i = m;
      }
    }
    return top;
  };
  let cnt = 0;
  for (const node of lists) {          // 1) 每条链表的当前头作为候选入堆
    if (node) push({ val: node.val, seq: cnt++, node });
  }
  const dummy = new ListNode(0);       // dummy 虚拟头节点：统一拼接起点
  let cur = dummy;
  while (heap.length) {                // 2) 反复弹出全局最小节点
    const { node } = pop();
    cur.next = node;                   // 接到结果尾部
    cur = cur.next;
    if (node.next) push({ val: node.next.val, seq: cnt++, node: node.next });
  }
  return dummy.next;
};

