func mergeKLists(lists []*ListNode) *ListNode {
	// 小根堆手写实现：元素为 (val, seq, node)，val 相同时比 seq，避免比较指针
	type item struct {
		val, seq int
		node     *ListNode
	}
	var heap []item
	push := func(it item) { // 尾部插入后一路上浮
		heap = append(heap, it)
		i := len(heap) - 1
		for i > 0 {
			p := (i - 1) / 2
			if heap[p].val < heap[i].val ||
				(heap[p].val == heap[i].val && heap[p].seq < heap[i].seq) {
				break
			}
			heap[i], heap[p] = heap[p], heap[i]
			i = p
		}
	}
	pop := func() item { // 弹出堆顶，尾元素补位后下沉归位
		top := heap[0]
		heap[0] = heap[len(heap)-1]
		heap = heap[:len(heap)-1]
		i, n := 0, len(heap)
		for {
			l, r, m := 2*i+1, 2*i+2, i
			if l < n && (heap[l].val < heap[m].val ||
				(heap[l].val == heap[m].val && heap[l].seq < heap[m].seq)) {
				m = l
			}
			if r < n && (heap[r].val < heap[m].val ||
				(heap[r].val == heap[m].val && heap[r].seq < heap[m].seq)) {
				m = r
			}
			if m == i {
				break
			}
			heap[i], heap[m] = heap[m], heap[i]
			i = m
		}
		return top
	}
	cnt := 0
	for _, node := range lists { // 1) 每条链表的当前头作为候选入堆
		if node != nil {
			push(item{node.Val, cnt, node})
			cnt++
		}
	}
	dummy := &ListNode{} // dummy 虚拟头节点：统一拼接起点
	cur := dummy
	for len(heap) > 0 { // 2) 反复弹出全局最小节点，接到结果尾部
		it := pop()
		cur.Next = it.node
		cur = cur.Next
		if it.node.Next != nil { // 该节点在原链表中的后继补进堆
			push(item{it.node.Next.Val, cnt, it.node.Next})
			cnt++
		}
	}
	return dummy.Next
}

