class Solution {
public:
    ListNode* reverseKGroup(ListNode* head, int k) {
        // dummy 虚拟头：第一组的组前驱也能统一表示，免去特判
        ListNode dummy(0, head);
        ListNode* prevGroup = &dummy;  // 上一组翻转后的尾节点，也是当前组的组前驱
        while (true) {
            // 1) 探路：从组前驱出发数 k 个，不足 k 个则剩余部分保持原序，直接结束
            ListNode* end = prevGroup;
            for (int i = 0; i < k && end; ++i) end = end->next;
            if (!end) return dummy.next;
            ListNode* nxt = end->next;     // 下一组开头，翻转期间被暂时断开
            // 2) 反转区间 [组头, end]：prev 初值设为 nxt，翻完后旧组头正好指向下一组
            ListNode* cur = prevGroup->next;
            ListNode* prev = nxt;
            ListNode* first = prevGroup->next;  // 记录旧组头，翻转后它变成组尾
            while (cur != nxt) {
                ListNode* tmp = cur->next;
                cur->next = prev;          // 箭头掉头
                prev = cur;
                cur = tmp;
            }
            // 3) 重接断点：prev 是新组头（原组尾），first 是新组尾（原组头）
            prevGroup->next = prev;        // 组前驱接新组头
            first->next = nxt;             // 新组尾接下一组开头
            prevGroup = first;             // 前移到下一组的组前驱
        }
    }
};

