class Solution {
public:
    ListNode* rotateRight(ListNode* head, int k) {
        // 边界：空链表、单节点或 k 为 0，旋转无意义
        if (!head || !head->next || k == 0) return head;
        // 1) 求长度 n，并顺带找到尾节点
        int n = 1;
        ListNode* tail = head;
        while (tail->next) {
            tail = tail->next;
            ++n;
        }
        k %= n;                  // k 可能大于 n，先取模
        if (k == 0) return head; // 取模后为 0，等价于不旋转
        tail->next = head;       // 2) 尾接头，闭合成环
        // 3) 新尾是第 n-k 个节点：从 head 走 n-k-1 步抵达
        ListNode* cur = head;
        for (int i = 0; i < n - k - 1; ++i) cur = cur->next;
        ListNode* newHead = cur->next;  // 新尾的 next 就是新头
        cur->next = nullptr;            // 断开环，链表到此为止
        return newHead;
    }
};

