class Solution {
public:
    ListNode* reverseBetween(ListNode* head, int left, int right) {
        // dummy：left=1（反转含头节点）时也需要前驱
        ListNode dummy(0, head);
        ListNode* pre = &dummy;
        // 1) 走 left-1 步，pre 定位到区间前驱
        for (int i = 0; i < left - 1; ++i) pre = pre->next;
        ListNode* cur = pre->next;  // 区间第一个节点，反转后成为区间尾，位置不再改变
        // 2) 头插 right-left 次：每次把 cur.next 摘下插到 pre 之后
        for (int i = 0; i < right - left; ++i) {
            ListNode* moved = cur->next;   // 待摘的节点
            cur->next = moved->next;       // 先摘：cur 跨过 moved 保持链接不断
            moved->next = pre->next;       // moved 反指已反转部分的新头
            pre->next = moved;             // pre 后面插入 moved，成为新头
        }
        return dummy.next;
    }
};

