// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（节点个数）
//   接下来 n 行：每行两个整数 val random_idx（random_idx 为该节点 random 指向的下标，
//               0 起；-1 表示指向 null）
// 输出格式：n 行，深拷贝链表每个节点的 val 与其 random 指向的下标，空格分隔
#include <bits/stdc++.h>
using namespace std;

struct Node {
    int val;
    Node* next;
    Node* random;
    Node(int x = 0) : val(x), next(nullptr), random(nullptr) {}
};

Node* build(const vector<pair<int, int>>& spec) {
    if (spec.empty()) return nullptr;
    vector<Node*> nodes;
    for (auto& [v, r] : spec) nodes.push_back(new Node(v));
    for (size_t i = 0; i + 1 < nodes.size(); ++i) nodes[i]->next = nodes[i + 1];
    for (size_t i = 0; i < nodes.size(); ++i) {
        if (spec[i].second >= 0) nodes[i]->random = nodes[spec[i].second];  // 挂 random
    }
    return nodes[0];
}

Node* copyRandomList(Node* head) {
    if (!head) return nullptr;
    Node* cur = head;
    while (cur) {                          // 1) 克隆节点插到原节点后
        Node* cp = new Node(cur->val);
        cp->next = cur->next;
        cur->next = cp;
        cur = cp->next;
    }
    cur = head;
    while (cur) {                          // 2) 补 random
        if (cur->random) cur->next->random = cur->random->next;
        cur = cur->next->next;
    }
    Node dummy(0);                         // 3) 交错拆分
    Node* copyTail = &dummy;
    cur = head;
    while (cur) {
        Node* cp = cur->next;
        copyTail->next = cp;
        copyTail = cp;
        cur->next = cp->next;
        cur = cur->next;
    }
    return dummy.next;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;
    vector<pair<int, int>> spec(n);
    for (auto& [v, r] : spec) cin >> v >> r;

