class Solution {
    public Node copyRandomList(Node head) {
        if (head == null) return null;
        // 第 1 步：把每个新节点插到对应原节点之后，形成 1 -> 1' -> 2 -> 2' ...
        Node cur = head;
        while (cur != null) {
            Node copy = new Node(cur.val);    // 只建节点，random 稍后补
            copy.next = cur.next;
            cur.next = copy;
            cur = copy.next;                  // 跳过拷贝，走向下一个原节点
        }
        // 第 2 步：补 random。原节点 random 的拷贝恰好是 random.next
        cur = head;
        while (cur != null) {
            if (cur.random != null) cur.next.random = cur.random.next;
            cur = cur.next.next;              // 每次跳两步：原 -> 拷贝 -> 原
        }
        // 第 3 步：交错拆分，恢复原链表的同时串起拷贝链
        Node dummy = new Node(0);
        Node copyTail = dummy;
        cur = head;
        while (cur != null) {
            Node copy = cur.next;             // 拷贝节点紧跟在原节点后
            copyTail.next = copy;             // 拷贝节点接入拷贝链
            copyTail = copy;
            cur.next = copy.next;             // 恢复原链表的 next
            cur = cur.next;                   // 移到下一个原节点
        }
        return dummy.next;
    }
}

