class Solution {
public:
    bool hasCycle(ListNode *head) {
        // 快慢指针：slow 每次走 1 步，fast 每次走 2 步
        ListNode *slow = head, *fast = head;
        while (fast && fast->next) {  // fast 走两步前，两个位置都必须存在
            slow = slow->next;        // 慢指针前进一步
            fast = fast->next->next;  // 快指针前进两步
            if (slow == fast)         // 比较节点身份（同一节点），不是节点值
                return true;          // 快指针追上慢指针：有环
        }
        // fast 或 fast->next 为空：走到了链表尽头，说明无环
        return false;
    }
};

