# ---- ListNode 定义与小型构造辅助（支持成环） ----
class ListNode:
    def __init__(self, val=0, next=None):
        self.val = val
        self.next = next

def build(nums, pos):
    """数组 -> 链表；pos 为尾节点连接到的下标（0 起），-1 表示无环。"""
    nodes = [ListNode(x) for x in nums]
    for i in range(len(nodes) - 1):
        nodes[i].next = nodes[i + 1]
    if nodes and pos >= 0:
        nodes[-1].next = nodes[pos]    # 制造环：尾节点指回第 pos 个
    return nodes[0] if nodes else None


# ---- 思路：先求环长再定位 ----
def detect_cycle(head):
    # 阶段一：快慢指针找相遇点
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            break
    else:
        return None                # while 正常结束：无环
    # 阶段二：从相遇点绕一圈数出环长 c
    c = 1
    node = slow.next
    while node is not slow:
        node = node.next
        c += 1
    # p 先走 c 步，再与 q 同步前进，相遇即入口
    p = q = head
    for _ in range(c):
        p = p.next
    while p is not q:
        p = p.next
        q = q.next
    return p

