// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：n（链表长度）
//   第二行：n 个整数（链表节点值）
// 输出格式：一行，升序排列后的序列，空格分隔（空链表输出空行）
#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* n = nullptr) : val(x), next(n) {}
};

ListNode* build(const vector<int>& nums) {
    ListNode dummy(0);
    ListNode* cur = &dummy;
    for (int x : nums) {
        cur->next = new ListNode(x);
        cur = cur->next;
    }
    return dummy.next;
}

ListNode* splitList(ListNode* head, int step) {
    while (step > 1 && head) {         // 从 head 起数 step 个节点
        head = head->next;
        --step;
    }
    if (!head) return nullptr;
    ListNode* nxt = head->next;
    head->next = nullptr;              // 掐断，保证每段独立
    return nxt;
}

ListNode* mergeLists(ListNode* l1, ListNode* l2, ListNode* prev) {
    ListNode* cur = prev;
    while (l1 && l2) {                 // 摘较小的头接到 prev 之后
        if (l1->val <= l2->val) {
            cur->next = l1;
            l1 = l1->next;
        } else {
            cur->next = l2;
            l2 = l2->next;
        }
        cur = cur->next;
    }
    cur->next = l1 ? l1 : l2;          // 接上剩余部分
    while (cur->next) cur = cur->next; // 返回合并结果的尾
    return cur;
}

ListNode* sortList(ListNode* head) {
    if (!head || !head->next) return head;
    int n = 0;                         // 先数出总长度
    for (ListNode* node = head; node; node = node->next) ++n;
    ListNode dummy(0, head);
    for (int step = 1; step < n; step *= 2) {  // 段长 1,2,4,8… 倍增
        ListNode* prev = &dummy;
        ListNode* cur = dummy.next;
        while (cur) {                  // 一轮：整条链按 step 分段，两两合并
            ListNode* left = cur;
            ListNode* right = splitList(left, step);
            cur = splitList(right, step);
            prev = mergeLists(left, right, prev);
        }
    }
    return dummy.next;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

