class Solution {
    public ListNode sortList(ListNode head) {
        if (head == null || head.next == null) return head;
        // 先数出总长度 n
        int n = 0;
        for (ListNode node = head; node != null; node = node.next) n++;
        ListNode dummy = new ListNode(0, head);
        // step：当前有序段的长度，按 1,2,4,8… 倍增（自底向上归并，免去递归栈）
        for (int step = 1; step < n; step *= 2) {
            ListNode prev = dummy;
            ListNode cur = dummy.next;
            while (cur != null) {                  // 一轮：整条链按 step 分段，两两合并
                ListNode left = cur;
                ListNode right = split(left, step);   // 切出第一段，right 是第二段头
                cur = split(right, step);             // 切出第二段，cur 是剩余部分头
                prev = merge(left, right, prev);      // 合并两段接回 prev，返回新尾
            }
        }
        return dummy.next;
    }

    // 从 head 起切出 step 个节点作为一段，断开链接，返回下一段的头
    private ListNode split(ListNode head, int step) {
        while (step > 1 && head != null) {
            head = head.next;
            step--;
        }
        if (head == null) return null;
        ListNode nxt = head.next;
        head.next = null;   // 掐断，保证每段独立
        return nxt;
    }

    // 把有序段 l1、l2 合并后接在 prev 之后，返回合并后的尾节点
    private ListNode merge(ListNode l1, ListNode l2, ListNode prev) {
        ListNode cur = prev;
        while (l1 != null && l2 != null) {   // 21 题的逻辑：摘较小的头
            if (l1.val <= l2.val) {
                cur.next = l1;
                l1 = l1.next;
            } else {
                cur.next = l2;
                l2 = l2.next;
            }
            cur = cur.next;
        }
        cur.next = (l1 != null) ? l1 : l2;   // 接上某一段的剩余部分
        while (cur.next != null) cur = cur.next;  // 走到合并结果的尾，供下一轮作 prev
        return cur;
    }
}

