			left := cur
			right := splitList(left, step)    // 切出第一段，right 是第二段头
			cur = splitList(right, step)      // 切出第二段，cur 是剩余部分头
			prev = mergeLists(left, right, prev) // 合并两段接回 prev，返回新尾
		}
	}
	return dummy.Next
}

// splitList 从 head 起切出 step 个节点作为一段，断开链接，返回下一段的头
func splitList(head *ListNode, step int) *ListNode {
	for step > 1 && head != nil {
		head = head.Next
		step--
	}
	if head == nil {
		return nil
	}
	nxt := head.Next
	head.Next = nil // 掐断，保证每段独立
	return nxt
}

// mergeLists 把有序段 l1、l2 合并后接在 prev 之后，返回合并后的尾节点
func mergeLists(l1, l2, prev *ListNode) *ListNode {
	cur := prev
	for l1 != nil && l2 != nil { // 21 题的逻辑：摘较小的头
		if l1.Val <= l2.Val {
			cur.Next = l1
			l1 = l1.Next
		} else {
			cur.Next = l2
			l2 = l2.Next
		}
		cur = cur.Next
	}
	if l1 == nil { // 接上某一段的剩余部分
		cur.Next = l2
	} else {
		cur.Next = l1
	}
	for cur.Next != nil { // 走到合并结果的尾，供下一轮作 prev
		cur = cur.Next
	}
	return cur
}

