// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：m（链表 A 长度）
//   第二行：m 个整数（链表 A）
//   第三行：n（链表 B 长度）
//   第四行：n 个整数（链表 B）
//   第五行：skipA skipB（相交时 A/B 从该下标起共享节点；-1 -1 表示不相交）
// 输出格式：一行，相交节点的值；不相交输出 null
#include <bits/stdc++.h>
using namespace std;

struct ListNode {
    int val;
    ListNode* next;
    ListNode(int x = 0, ListNode* n = nullptr) : val(x), next(n) {}
};

// 构造可能相交的两条链表：相交时 B 的前 skipB 个自建，之后共享 A 的后缀
pair<ListNode*, ListNode*> buildIntersect(const vector<int>& a, const vector<int>& b,
                                          int skipA, int skipB) {
    vector<ListNode*> nodesA;
    for (int x : a) nodesA.push_back(new ListNode(x));
    for (size_t i = 0; i + 1 < nodesA.size(); ++i) nodesA[i]->next = nodesA[i + 1];
    ListNode* headA = nodesA.empty() ? nullptr : nodesA[0];
    if (skipA < 0) {                   // 不相交：B 整条自建
        ListNode dummy(0);
        ListNode* cur = &dummy;
        for (int x : b) {
            cur->next = new ListNode(x);
            cur = cur->next;
        }
        return {headA, dummy.next};
    }
    // 相交：B 前半段自建，尾部接上 A 的共享后缀
    ListNode dummy(0);
    ListNode* cur = &dummy;
    for (int i = 0; i < skipB; ++i) {
        cur->next = new ListNode(b[i]);
        cur = cur->next;
    }
    cur->next = nodesA[skipA];
    return {headA, dummy.next};
}

ListNode* getIntersectionNode(ListNode* headA, ListNode* headB) {
    ListNode *pA = headA, *pB = headB;
    while (pA != pB) {                 // 走到尾就换到另一条链表继续
        pA = pA ? pA->next : headB;
        pB = pB ? pB->next : headA;
    }
    return pA;                         // 相交节点，或双双为 nullptr
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int m;
    cin >> m;
    vector<int> a(m);
    for (auto& x : a) cin >> x;
    int n;
    cin >> n;
    vector<int> b(n);
    for (auto& x : b) cin >> x;
    int skipA, skipB;
    cin >> skipA >> skipB;

    auto [headA, headB] = buildIntersect(a, b, skipA, skipB);
    ListNode* node = getIntersectionNode(headA, headB);
    if (!node) {
        cout << "null" << endl;
    } else {
        cout << node->val << endl;     // 输出相交节点的值
    }
    return 0;
}

