class Solution {
public:
    bool isPalindrome(ListNode* head) {
        if (!head || !head->next) return true;
        // 1) 快慢指针找中点：slow 最终停在前半段的最后一个节点
        ListNode *slow = head, *fast = head;
        while (fast->next && fast->next->next) {
            slow = slow->next;
            fast = fast->next->next;
        }
        // 2) 反转后半段（slow->next 之后的部分），得到逆序的后半段
        ListNode* second = reverse(slow->next);
        // 3) 前半段与反转后的后半段同步逐节点比较
        ListNode *p1 = head, *p2 = second;
        bool result = true;
        while (p2) {                  // 以后半段为准：它不长于前半段
            if (p1->val != p2->val) {
                result = false;
                break;
            }
            p1 = p1->next;
            p2 = p2->next;
        }
        // 4) 恢复链表：把后半段再反转回去接回 slow 后面
        slow->next = reverse(second);
        return result;
    }

private:
    // 206 的标准迭代反转
    ListNode* reverse(ListNode* head) {
        ListNode *prev = nullptr, *cur = head;
        while (cur) {
            ListNode* nxt = cur->next;
            cur->next = prev;
            prev = cur;
            cur = nxt;
        }
        return prev;
    }
};

