	second := reverseList(slow.Next)
	// 3) 前半段与反转后的后半段同步逐节点比较
	p1, p2 := head, second
	result := true
	for p2 != nil { // 以后半段为准：它不长于前半段
		if p1.Val != p2.Val {
			result = false
			break
		}
		p1 = p1.Next
		p2 = p2.Next
	}
	// 4) 恢复链表：把后半段再反转回去接回 slow 后面
	slow.Next = reverseList(second)
	return result
}

// reverseList 是 206 的标准迭代反转
func reverseList(head *ListNode) *ListNode {
	var prev *ListNode
	cur := head
	for cur != nil {
		nxt := cur.Next
		cur.Next = prev
		prev = cur
		cur = nxt
	}
	return prev
}

