class LRUCache {
    // 双向链表节点：必须同时存 key，淘汰尾节点时才能反查哈希表删除映射
    struct Node {
        int key, val;
        Node *prev, *next;
        Node(int k = 0, int v = 0) : key(k), val(v), prev(nullptr), next(nullptr) {}
    };

    int cap;
    unordered_map<int, Node*> cache;  // 哈希表：key -> 节点，负责 O(1) 定位
    Node head, tail;                  // 头尾哨兵：head.next 是最近使用，tail.prev 是最久未使用

    // 从链表摘除 node：双向链表 O(1)，无需遍历找前驱
    void remove(Node* node) {
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    // 把 node 插到哨兵 head 之后，表示『最近使用』
    void addFront(Node* node) {
        node->next = head.next;
        node->prev = &head;
        head.next->prev = node;
        head.next = node;
    }

public:
    LRUCache(int capacity) : cap(capacity) {
        head.next = &tail;  // 初始只有两个哨兵互指
        tail.prev = &head;
    }

    int get(int key) {
        auto it = cache.find(key);
        if (it == cache.end()) return -1;  // 未命中
        Node* node = it->second;
        remove(node);       // 先摘下
        addFront(node);     // 再挪到头部 = 标记为最近使用
        return node->val;
    }

    void put(int key, int value) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            Node* node = it->second;
            node->val = value;  // 已存在：更新值并挪到头部
            remove(node);
            addFront(node);
        } else {
            if ((int)cache.size() >= cap) {
                Node* lru = tail.prev;   // 尾哨兵的前一个 = 最久未使用
                remove(lru);
                cache.erase(lru->key);   // 节点里存 key 就是为了这一步反查
                delete lru;
            }
            Node* node = new Node(key, value);
            cache[key] = node;
            addFront(node);
        }
    }
};

problems.acmCodeCpp:
// ACM 模式：完整可运行程序（stdin -> stdout）
// 输入格式：
//   第一行：capacity（缓存容量）
//   随后每行一个操作，直到 EOF：
//     get k     —— 读取 key 为 k 的值
//     put k v   —— 写入 key=k, value=v
// 输出格式：一行，所有 get 操作的结果，按执行顺序空格分隔（无 get 输出空行）
#include <bits/stdc++.h>
using namespace std;

struct Node {
    int key, val;
    Node *prev, *next;
    Node(int k = 0, int v = 0) : key(k), val(v), prev(nullptr), next(nullptr) {}
};

class LRUCache {
    int cap;
    unordered_map<int, Node*> cache;  // 哈希表：key -> 节点，负责 O(1) 定位
    Node head, tail;                  // 头尾哨兵：head.next 是最近使用，tail.prev 是最久未使用

    void remove(Node* node) {         // 从链表摘除 node：双向链表 O(1)
        node->prev->next = node->next;
        node->next->prev = node->prev;
    }

    void addFront(Node* node) {       // 插到哨兵 head 之后，表示『最近使用』
        node->next = head.next;
        node->prev = &head;
        head.next->prev = node;
        head.next = node;
    }

public:
    LRUCache(int capacity) : cap(capacity) {
        head.next = &tail;
        tail.prev = &head;
    }

    int get(int key) {
        auto it = cache.find(key);
        if (it == cache.end()) return -1;
        Node* node = it->second;
        remove(node);                 // 先摘下再挪到头部 = 标记为最近使用
        addFront(node);
        return node->val;
    }

    void put(int key, int value) {
        auto it = cache.find(key);
        if (it != cache.end()) {
            Node* node = it->second;
            node->val = value;        // 已存在：更新值并挪到头部
            remove(node);
            addFront(node);
        } else {
            if ((int)cache.size() >= cap) {
                Node* lru = tail.prev;  // 尾哨兵的前一个 = 最久未使用
                remove(lru);
                cache.erase(lru->key);  // 节点里存 key 就是为了这一步反查
                delete lru;
            }
            Node* node = new Node(key, value);
            cache[key] = node;
            addFront(node);
        }
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int cap;
    if (!(cin >> cap)) return 0;
    LRUCache cache(cap);
    string op;
    string out;
    while (cin >> op) {               // 逐 token 解析操作序列直到 EOF
        if (op == "get") {
            int k;
            cin >> k;
            if (!out.empty()) out += ' ';
            out += to_string(cache.get(k));
        } else if (op == "put") {
            int k, v;
            cin >> k >> v;
            cache.put(k, v);
        }
    }
    cout << out << endl;
    return 0;
}

