class LRUCache {
    // 双向链表节点：必须同时存 key，淘汰尾节点时才能反查哈希表删除映射
    private static class Node {
        int key, val;
        Node prev, next;
        Node(int k, int v) { key = k; val = v; }
    }

    private final int cap;
    private final Map<Integer, Node> cache = new HashMap<>();  // 哈希表：key -> 节点，O(1) 定位
    private final Node head = new Node(0, 0);  // 头哨兵：head.next 是最近使用
    private final Node tail = new Node(0, 0);  // 尾哨兵：tail.prev 是最久未使用

    public LRUCache(int capacity) {
        cap = capacity;
        head.next = tail;   // 初始只有两个哨兵互指
        tail.prev = head;
    }

    // 从链表摘除 node：双向链表 O(1)，无需遍历找前驱
    private void remove(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    // 把 node 插到哨兵 head 之后，表示『最近使用』
    private void addFront(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    public int get(int key) {
        Node node = cache.get(key);
        if (node == null) return -1;  // 未命中
        remove(node);   // 先摘下
        addFront(node); // 再挪到头部 = 标记为最近使用
        return node.val;
    }

    public void put(int key, int value) {
        Node node = cache.get(key);
        if (node != null) {
            node.val = value;  // 已存在：更新值并挪到头部
            remove(node);
            addFront(node);
        } else {
            if (cache.size() >= cap) {
                Node lru = tail.prev;   // 尾哨兵的前一个 = 最久未使用
                remove(lru);
                cache.remove(lru.key);  // 节点里存 key 就是为了这一步反查
            }
            node = new Node(key, value);
            cache.put(key, node);
            addFront(node);
        }
    }
}

problems.codeJs:
/**
 * LRU 缓存：哈希表（O(1) 定位）+ 双向链表（O(1) 维护使用次序）
 * @param {number} capacity 缓存容量
 */
var LRUCache = function (capacity) {
  this.cap = capacity;
  this.cache = new Map();   // 哈希表：key -> 节点，负责 O(1) 定位
  // 头尾哨兵：head.next 是最近使用，tail.prev 是最久未使用
  this.head = { key: 0, val: 0, prev: null, next: null };
  this.tail = { key: 0, val: 0, prev: null, next: null };
  this.head.next = this.tail;  // 初始只有两个哨兵互指
  this.tail.prev = this.head;
};

/** 从链表摘除 node：双向链表 O(1)，无需遍历找前驱 */
LRUCache.prototype._remove = function (node) {
  node.prev.next = node.next;
  node.next.prev = node.prev;
};

/** 把 node 插到哨兵 head 之后，表示『最近使用』 */
LRUCache.prototype._addFront = function (node) {
  node.next = this.head.next;
  node.prev = this.head;
  this.head.next.prev = node;
  this.head.next = node;
};

/**
 * @param {number} key
 * @return {number} key 对应的值；不存在返回 -1
 */
LRUCache.prototype.get = function (key) {
  const node = this.cache.get(key);
  if (node === undefined) return -1;  // 未命中
  this._remove(node);                 // 先摘下
  this._addFront(node);               // 再挪到头部 = 标记为最近使用
  return node.val;
};

/**
 * @param {number} key
 * @param {number} value
 * @return {void}
 */
LRUCache.prototype.put = function (key, value) {
  const node = this.cache.get(key);
  if (node !== undefined) {
    node.val = value;  // 已存在：更新值并挪到头部
    this._remove(node);
    this._addFront(node);
  } else {
    if (this.cache.size >= this.cap) {
      const lru = this.tail.prev;  // 尾哨兵的前一个 = 最久未使用
      this._remove(lru);
      this.cache.delete(lru.key);  // 节点里存 key 就是为了这一步反查
    }
    const fresh = { key: key, val: value, prev: null, next: null };
    this.cache.set(key, fresh);
    this._addFront(fresh);
  }
};

