// node 是双向链表节点：必须同时存 key，淘汰尾节点时才能反查哈希表删除映射
type node struct {
	key, val   int
	prev, next *node
}

// LRUCache = 哈希表（O(1) 定位）+ 双向链表（O(1) 维护使用次序）
type LRUCache struct {
	cap        int
	cache      map[int]*node
	head, tail *node // 头尾哨兵：head.next 是最近使用，tail.prev 是最久未使用
}

func Constructor(capacity int) LRUCache {
	h, t := &node{}, &node{}
	h.next, t.prev = t, h // 初始只有两个哨兵互指
	return LRUCache{cap: capacity, cache: map[int]*node{}, head: h, tail: t}
}

// removeNode 从链表摘除 n：双向链表 O(1)，无需遍历找前驱
func (c *LRUCache) removeNode(n *node) {
	n.prev.next = n.next
	n.next.prev = n.prev
}

// addFront 把 n 插到哨兵 head 之后，表示『最近使用』
func (c *LRUCache) addFront(n *node) {
	n.next = c.head.next
	n.prev = c.head
	c.head.next.prev = n
	c.head.next = n
}

func (c *LRUCache) Get(key int) int {
	n, ok := c.cache[key]
	if !ok {
		return -1 // 未命中
	}
	c.removeNode(n) // 先摘下
	c.addFront(n)   // 再挪到头部 = 标记为最近使用
	return n.val
}

func (c *LRUCache) Put(key int, value int) {
	if n, ok := c.cache[key]; ok {
		n.val = value // 已存在：更新值并挪到头部
		c.removeNode(n)
		c.addFront(n)
		return
	}
	if len(c.cache) >= c.cap {
		lru := c.tail.prev // 尾哨兵的前一个 = 最久未使用
		c.removeNode(lru)
		delete(c.cache, lru.key) // 节点里存 key 就是为了这一步反查
	}
	n := &node{key: key, val: value}
	c.cache[key] = n
	c.addFront(n)
}
